#!/usr/bin/env python3
"""Sync the latest resume into the existing GitHub portfolio.

Run this script from the root of the local github-portfolio repository:
    python3 sync_latest_resume_to_portfolio.py

The script creates a backup, writes the latest resume into docs/assets using a
clean public filename, and updates the homepage Resume link.
"""

from pathlib import Path
from datetime import datetime
import base64
import re
import shutil
import sys

ROOT = Path.cwd()
INDEX = ROOT / "docs" / "index.html"
ASSETS = ROOT / "docs" / "assets"
TARGET = ASSETS / "Paresh_Maheshwari_Resume.docx"

if not INDEX.exists():
    print("Run this script from the root of your github-portfolio folder.")
    print("Expected file: docs/index.html")
    sys.exit(1)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup = ROOT / f".resume_sync_backup_{stamp}"
backup.mkdir(parents=True, exist_ok=True)
shutil.copy2(INDEX, backup / "index.html")

ASSETS.mkdir(parents=True, exist_ok=True)
if TARGET.exists():
    shutil.copy2(TARGET, backup / TARGET.name)

resume_data = base64.b64decode('')
TARGET.write_bytes(resume_data)

text = INDEX.read_text(encoding="utf-8")
new_href = "assets/Paresh_Maheshwari_Resume.docx"
pattern = r'(<a\b[^>]*?href=")[^"]*("[^>]*>\s*View résumé\s*</a>)'
updated, count = re.subn(pattern, lambda m: m.group(1) + new_href + m.group(2), text, count=1, flags=re.I | re.S)

if count == 0:
    print("The resume was copied, but the View résumé link could not be found.")
    print(f"Resume location: {TARGET}")
    sys.exit(2)

INDEX.write_text(updated, encoding="utf-8")

print("Latest resume synchronized successfully.")
print(f"Resume asset: {TARGET}")
print(f"Backup: {backup}")
print("")
print("Preview:")
print("  python3 -m http.server 8000 --directory docs")
print("  open http://localhost:8000")
print("")
print("Publish after review:")
print("  git add .")
print('  git commit -m "Update portfolio resume"')
print("  git push")
